// Writes src/bookings/leaflet-bundle.ts from the web's installed Leaflet, so the map page needs no
// CDN and no package here (F37). Run it from mobile/ after the web moves to a new Leaflet:
//   node scripts/vendor-leaflet.mjs
import { readFileSync, writeFileSync } from "node:fs";

const dist = "../web/node_modules/leaflet/dist";
const { version } = JSON.parse(readFileSync("../web/node_modules/leaflet/package.json", "utf8"));
const js = readFileSync(`${dist}/leaflet.js`, "utf8").replace(/\n\/\/# sourceMappingURL=.*\s*$/, "\n");
const css = readFileSync(`${dist}/leaflet.css`, "utf8");

writeFileSync(
  "src/bookings/leaflet-bundle.ts",
  `/* Generated by scripts/vendor-leaflet.mjs from Leaflet ${version} (BSD-2-Clause, (c) 2010-2023 Vladimir Agafonkin,
   (c) 2010-2011 CloudMade). Do not edit. */
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`,
);
